484	/// Write-Ahead Log
485	pub struct Wal {
486	    db: *mut ffi::sqlite3,
487	    db_name: *const c_char,
488	}
489	
490	impl Wal {
491	    /// Checkpoint a database
492	    pub fn checkpoint(&self) -> Result<()> {
493	        unsafe { decode_result_raw(self.db, ffi::sqlite3_wal_checkpoint(self.db, self.db_name)) }
494	    }
495	
496	    /// Checkpoint a database
497	    pub fn checkpoint_v2(&self, mode: CheckpointMode) -> Result<(c_int, c_int)> {
498	        let mut n_log = 0;
499	        let mut n_ckpt = 0;
500	        unsafe {
501	            decode_result_raw(
502	                self.db,
503	                ffi::sqlite3_wal_checkpoint_v2(
504	                    self.db,
505	                    self.db_name,
506	                    mode as c_int,
507	                    &raw mut n_log,
508	                    &raw mut n_ckpt,
509	                ),
510	            )?;
511	        };
512	        Ok((n_log, n_ckpt))
513	    }
514	
515	    /// Name of the database that was written to
516	    #[must_use]
517	    pub fn name(&self) -> &CStr {
518	        unsafe { CStr::from_ptr(self.db_name) }
519	    }
520	}
