587	type WalHook = Box<dyn FnMut(&Wal, c_int) -> Result<()> + Send>;
588	
589	/// The wal hook registered on a connection.
590	struct WalHookState {
591	    hook: WalHook,
592	    /// The reason the hook rejected the most recent notification, to be
593	    /// reported by the call that observes SQLite's generic `SQLITE_ERROR`
594	    /// (the notification happens after the commit, so SQLite cannot
595	    /// attribute the failure more precisely). Reset on every hook
596	    /// invocation, so a stale reason can never be attributed to a later
597	    /// failure.
598	    error: Option<Error>,
599	}
600	
601	unsafe extern "C" fn wal_hook_callback(
602	    client_data: *mut c_void,
603	    db: *mut ffi::sqlite3,
604	    db_name: *const c_char,
605	    pages: c_int,
606	) -> c_int {
607	    unsafe {
608	        let state: *mut WalHookState = client_data.cast();
609	        let wal = Wal { db, db_name };
610	        (*state).error = None;
611	        let r = catch_unwind(AssertUnwindSafe(|| ((*state).hook)(&wal, pages)));
612	        let error = match r {
613	            Ok(Ok(())) => return ffi::SQLITE_OK,
614	            Ok(Err(err)) => err,
615	            Err(_) => Error::UnwindingPanic,
616	        };
617	        (*state).error = Some(error);
618	        ffi::SQLITE_ERROR
