622	/// If `code` is the generic `SQLITE_ERROR` that SQLite produces when the wal
623	/// hook on `db` failed and the currently registered hook provided a reason,
624	/// take and return it. The reason is consumed, so it is reported at most
625	/// once, by the call that triggered the notification.
626	pub(crate) unsafe fn take_wal_hook_error(db: *mut ffi::sqlite3, code: c_int) -> Option<Error> {
627	    if db.is_null() || code != ffi::SQLITE_ERROR {
628	        return None;
629	    }
630	    let state = unsafe { ffi::sqlite3_get_clientdata(db, c"sqlite3_wal_hook".as_ptr()) }
631	        .cast::<WalHookState>();
632	    if state.is_null() {
633	        return None;
634	    }
635	    unsafe { (*state).error.take() }
636	}
