            Err(Error::ToSqlConversionFailure(
                format!("wal error {n}").into(),
            ))
        }))?;
        let e1 = db.execute("INSERT INTO foo VALUES (1)", []).unwrap_err();
        let e2 = db.execute("INSERT INTO foo VALUES (2)", []).unwrap_err();
